syntax = "proto3";
package demo;

message Widget {
  string id = 1;
  optional string display_name = 2;
  int32 count = 3;
  optional uint64 big = 4;
  double ratio = 5;
  bool enabled = 6;
  repeated string tags = 7;
  map<string, string> labels = 8;
  bytes blob = 9;
  // @state persisted_shared
  string status = 10;
  nested.Type ref = 11;
  repeated bytes chunks = 12;
  // plain comment
  optional bool flag = 13;
}

message Other { string zzz = 1; }

